export type Dims = {
  speed: number; // speed and decisiveness
  stabilize: number; // addressing the immediate/acute problem
  resource: number; // tools, self-reliance, tactical execution
  strategy: number; // long-term / strategic thinking
  risk: number; // risk awareness and downside protection
};

export const DIMENSION_LABELS: Record<keyof Dims, string> = {
  speed: "Speed & decisiveness",
  stabilize: "Immediate stabilization",
  resource: "Resourcefulness",
  strategy: "Long-term strategy",
  risk: "Risk awareness",
};

export type ScenarioItem = { id: number; name: string; rank: number; dims: Dims; reasoning: string };

export type Scenario = {
  id: string;
  track: "business" | "survival" | "custom";
  title: string;
  setup: string;
  briefing: string;
  mechanicName: string;
  mechanicDesc: string;
  items: ScenarioItem[];
};

export function expertOrder(scenario: Scenario): number[] {
  return [...scenario.items].sort((a, b) => a.rank - b.rank).map((i) => i.id);
}

export function itemName(scenario: Scenario, id: number): string {
  return scenario.items.find((i) => i.id === id)?.name ?? "Unknown item";
}

export function itemReasoning(scenario: Scenario, id: number): string {
  return scenario.items.find((i) => i.id === id)?.reasoning ?? "";
}

